set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; L=$LD/revalidate_0315.log; SP=${SCRATCH:-/tmp/claude-1000/-home-tue037807/f56af2dd-c080-4e10-9195-a1c5aab65da2/scratchpad}
log() { echo "[$(date +%T)] $*" | tee -a "$L"; }
log "revalidate start (pid $$)"
run1() { local N=$1 S=$2; local NAME WS A V T0=$SECONDS
  NAME=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1]))['name'])" "tests/synth/generated/${N}_s1.json"); WS=$HOME/fish_synth/ws_$NAME; A=$HOME/fish_traces/analysis_$S; V=$HOME/fish_traces/synth_runs/verify_$NAME.txt
