  log "  $N $S: $(grep -h VERDICT "$V" | tail -1) $(grep -h 'false positives' "$V" | tail -1 | cut -c1-100) ($((SECONDS - T0)) s)"
  grep -E '^  trigger +(MISSING|found-not-exact) |^  (join|sampled) +MISSING ' "$V" | sed 's/^/      /' | tee -a "$L" >/dev/null; }
for N in chain tree star bipartite layered er ba cycle; do S=$(grep -h '^\[synth\] session' "$LD/synth2_${N}_s1.log" 2>/dev/null | tail -1 | awk '{print $3}'); [ -n "$S" ] && run1 "$N" "$S"; done
for N in er50 layered100 er200 ba500; do S=$(grep -h '^\[synth\] session' "$LD/synth_${N}_s1.log" 2>/dev/null | tail -1 | awk '{print $3}'); [ -n "$S" ] && run1 "$N" "$S"; done
